const $=s=>document.querySelector(s);
const en={brand:'حكاية',navExplore:'Explore stories',navHow:'How it works',navPricing:'Plans & pricing',library:'My library',bhdLogin:'BHD sign-in',start:'Create a story ↗',eyebrow:'Little imaginations. Extraordinary stories.',headline:'Not just in<br>the story.<br><span>Your child is the hero.</span>',description:'Turn your child’s photo into the beginning of an unforgettable adventure. Illustrated stories, superheroes, and worlds of wonder — made just for them.',createNow:'Create their story ✧',watch:'Watch the story',note1:'✧ Arabic & English',note2:'♡ Made for little ones',note3:'Interactive demo',artLabel:'Little imagination, endless possibilities',exampleLabel:'From the world of Hikaya',exampleTitle:'Isa & the guardian of the forest',artTag:'Every story starts with your child',formatsIntro:'One little story.<br><b>So many ways to wonder.</b>',formatBook:'Illustrated storybooks',formatVideo:'Video adventures',formatDraw:'Art & characters',formatPrint:'Books delivered to your door',worldsOverline:'WORLDS WAITING FOR THEIR HERO',worldsTitle:'Where will their imagination go today?',worldsDescription:'Choose the adventure. Give your child the leading role.',all:'All adventures',heroes:'Superheroes',fantasy:'Fantasy worlds',forestTag:'Courage & friendship',spaceTag:'Curiosity & discovery',oceanTag:'Imagination & wonder',age:'For ages 4–10',forestTitle:'Guardian of the enchanted forest',spaceTitle:'A mission among the stars',oceanTitle:'Secret of the coral kingdom',forestDesc:'A brave heart, a little friend, a big adventure.',spaceDesc:'A journey where dreams know no limits.',oceanDesc:'The treasures of the deep await their hero.',howOverline:'FROM A PHOTO TO A STORY',howTitle:'A little from you. A world of magic.',step1Title:'Meet the little hero',step1Desc:'Add their name, age, photo, and the things they love.',step2Title:'Choose their world',step2Desc:'A space adventure? A superhero? You choose the beginning.',step3Title:'Bring the story to life',step3Desc:'Preview and edit the words to make their story your own.',step4Title:'Keep the wonder',step4Desc:'Download the story or explore a printed keepsake.',pricingOverline:'MEMORIES, YOUR WAY',pricingTitle:'Choose how their story lives on.',priceNote:'Illustrative prices in OMR · Payments not activated',digital:'The digital story',printed:'The printed storybook',cinema:'The cinematic story',currency:'OMR',digitalDesc:'A personalized picture book to read anytime.',printedDesc:'From a world of wonder to their little bookshelf.',cinemaDesc:'Their favorite adventure, in their very own film.',feature1:'A 12-page illustrated story',feature2:'Downloadable story file',feature3:'Arabic or English',feature4:'Hardcover · 21 × 21 cm',feature5:'Digital copy included',feature6:'Delivery to your address',feature7:'Animated story scenes',feature8:'Video download after generation',feature9:'Video generation service required',chooseDigital:'Choose a digital story',choosePrint:'Design their first book ↗',chooseVideo:'Explore the video story',keepsake:'A lasting keepsake',faqTitle:'Little questions. Clear answers.',q1:'Does this actually transform my child’s photo with AI?',a1:'This interactive demo uses original sample illustrations. Personalized AI image and video generation require service activation. Your chosen photo stays in this browser and is never uploaded to a server.',q2:'Can I order a book and pay now?',a2:'You can customize a book and review an order. Payment, printing, and shipping are not activated. No money is collected and no real order is placed.',q3:'Are stories available in Arabic and English?',a3:'Yes. Choose the story language independently from the interface. Edit the preview and save the story to your device.',ctaTitle:'The best story? The one that starts with them.',ctaDesc:'Give their imagination a home. Give them the leading role.',footer:'Made for big little imaginations. © 2026 Hikaya',privacy:'Privacy',terms:'Terms',status:'Product status',studioLabel:'HIKAYA STUDIO'};
const ar={};document.querySelectorAll('[data-t]').forEach(e=>ar[e.dataset.t]=e.innerHTML);
let lang=localStorage.getItem('hikaya-language')==='en'?'en':'ar';
const t=(a,e)=>lang==='ar'?a:e;
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
function setLanguage(){document.documentElement.lang=lang;document.documentElement.dir=lang==='ar'?'rtl':'ltr';document.querySelectorAll('[data-t]').forEach(e=>e.innerHTML=(lang==='en'?en:ar)[e.dataset.t]||ar[e.dataset.t]);$('#language').innerHTML=lang==='ar'?'EN <span>◎</span>':'عربي <span>◎</span>';document.title=t('حكاية | مغامرة صغيرة، بطل كبير','Hikaya | Little heroes, extraordinary stories');try{localStorage.setItem('hikaya-language',lang)}catch{} }
$('#language').onclick=()=>{lang=lang==='ar'?'en':'ar';setLanguage()};setLanguage();
let toastTimer;function toast(s){$('#toast').textContent=s;$('#toast').classList.add('visible');clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('#toast').classList.remove('visible'),4500)}
document.querySelectorAll('[data-close]').forEach(b=>b.onclick=()=>b.closest('dialog').close());
document.querySelectorAll('dialog').forEach(d=>{d.addEventListener('click',e=>{if(e.target===d){const r=d.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)d.close()}});d.addEventListener('close',()=>{speechSynthesis.cancel()})});
document.querySelectorAll('[data-filter]').forEach(b=>b.onclick=()=>{document.querySelectorAll('[data-filter]').forEach(e=>e.classList.toggle('active',e===b));document.querySelectorAll('.story-card').forEach(c=>c.hidden=b.dataset.filter!=='all'&&!c.dataset.kind.includes(b.dataset.filter))});
const worlds=['forest','space','ocean'];
const titleFor=(w,l=lang)=> (l==='ar'?ar:en)[w+'Title'];
let draft={},step=0,story=null,page=0;
function start(world='forest',plan='digital'){draft={name:'',age:'6',storyLanguage:lang,world,plan,photo:'',consent:false,dedication:''};step=0;$('#studio').showModal();renderStudio()}
document.querySelectorAll('[data-create]').forEach(b=>b.onclick=()=>start('forest',b.dataset.plan||'digital'));
document.querySelectorAll('[data-world]').forEach(b=>b.onclick=()=>start(b.dataset.world));
function renderStudio(){
 $('#modalTitle').textContent=[t('لنتعرّف على بطل الحكاية','Meet your story’s hero'),t('لكل بطل عالمه الخاص','Every hero needs a world'),t('حكايته جاهزة للمعاينة','Their story preview'),t('كتاب صغير، ذكرى كبيرة','A book to keep forever')][step];
 const progress=`<div class="studio-progress">${[0,1,2,3].map(n=>`<span class="${n<=step?'on':''}"></span>`).join('')}</div>`;
 const note=`<p class="notice">${t('معاينة برسوم عائلية مُعدّة مسبقًا. تحويل صورة جديدة وتوليد الفيديو والدفع تحتاج تفعيل الخدمات.','Preview with prepared family artwork. Transforming new photos, AI video generation and payment require service activation.')}</p>`;
 let content='';
 if(step===0)content=`<form id="heroForm"><div class="form-grid"><label class="field">${t('اسم الطفل','Child’s name')}<input name="name" required maxlength="30" value="${esc(draft.name)}" placeholder="${t('مثلًا: عيسى','e.g. Isa')}" autocomplete="off"></label><label class="field">${t('العمر','Age')}<select name="age">${[4,5,6,7,8,9,10].map(n=>`<option ${String(n)===draft.age?'selected':''}>${n}</option>`).join('')}</select></label><label class="field">${t('لغة القصة','Story language')}<select name="storyLanguage"><option value="ar" ${draft.storyLanguage==='ar'?'selected':''}>العربية</option><option value="en" ${draft.storyLanguage==='en'?'selected':''}>English</option></select></label><label class="field">${t('إهداء صغير (اختياري)','A little dedication (optional)')}<input name="dedication" maxlength="120" value="${esc(draft.dedication)}" placeholder="${t('إلى بطلي الصغير…','To my little hero…')}"></label><div class="field full upload"><img id="photoPreview" src="${draft.photo||'assets/hero-family.png'}" alt="${t('معاينة صورة البطل','Hero photo preview')}"><div><strong>${t('صورة البطل (اختياري)','Hero photo (optional)')}</strong><p>${t('JPG أو PNG أو WebP، حتى ٥ ميجابايت. تبقى على جهازك.','JPG, PNG or WebP, up to 5 MB. Stays on your device.')}</p><input type="file" id="photo" accept="image/jpeg,image/png,image/webp" aria-label="${t('اختيار صورة الطفل','Choose child photo')}"></div></div><label class="check field full"><input type="checkbox" name="consent" required ${draft.consent?'checked':''}><span>${t('أنا وليّ الأمر أو مخوّل باستخدام الصورة، وأوافق على استخدامها في هذه المعاينة المحلية.','I am a parent or authorized to use this photo and consent to using it in this local preview.')}</span></label></div>${note}<div class="form-actions"><span></span><button class="button" type="submit">${t('اختر عالم الحكاية ←','Choose their world →')}</button></div></form>`;
 if(step===1)content=`<div class="mini-worlds">${worlds.map(w=>`<button class="mini-world ${draft.world===w?'selected':''}" data-select-world="${w}"><div class="world-image ${w}"></div><strong>${esc(titleFor(w))}</strong></button>`).join('')}</div><div class="form-grid" style="margin-top:20px"><label class="field full">${t('كيف تريد الاحتفاظ بالقصة؟','How would you like to keep the story?')}<select id="plan"><option value="digital" ${draft.plan==='digital'?'selected':''}>${t('قصة رقمية — 4.900 ر.ع','Digital story — OMR 4.900')}</option><option value="print" ${draft.plan==='print'?'selected':''}>${t('كتاب مطبوع — 14.900 ر.ع','Printed book — OMR 14.900')}</option><option value="video" ${draft.plan==='video'?'selected':''}>${t('فيديو — 9.900 ر.ع','Video story — OMR 9.900')}</option></select></label></div>${note}<div class="form-actions"><button class="button outline" id="back">${t('رجوع','Back')}</button><button class="button" id="makeStory">${t('أنشئ المعاينة ✧','Create the preview ✧')}</button></div>`;
 if(step===2)content=`<div class="preview-layout"><div class="book-cover"><div class="world-image ${story.world}"></div><h3>${esc(story.title)}</h3></div><div class="preview-text"><span class="badge">${t('قصة نموذجية قابلة للتحرير · ١٢ صفحة','Editable sample story · 12 pages')}</span><div class="scene-nav"><button id="prevPage" aria-label="Previous">←</button><span>${t('صفحة','Page')} ${page+1} / ${story.pages.length}</span><button id="nextPage" aria-label="Next">→</button></div><label class="field">${t('حرّر نص هذه الصفحة','Edit this page')}<textarea id="pageText" rows="5" dir="${story.language==='ar'?'rtl':'ltr'}">${esc(story.pages[page])}</textarea></label><p style="font-size:10px;color:#888">${t('رسوم مخصّصة مسبقًا من صور هذه النسخة العائلية؛ رفع صورة جديدة لا يغيّرها تلقائيًا.','Artwork is prepared from this family edition’s reference photos. New uploads do not change it automatically.')}</p><div class="downloads"><button class="button" id="saveStory">${t('حفظ في مكتبتي','Save to my library')}</button><button class="button outline" id="downloadStory">${t('تنزيل القصة','Download story')}</button><button class="button outline" id="filmPreview">${t('معاينة فيديو','Preview video')}</button></div></div></div><div class="form-actions"><button class="button outline" id="back">${t('تغيير العالم','Change world')}</button><button class="button" id="orderBook">${t('معاينة طلب الكتاب ←','Preview book order →')}</button></div>`;
 if(step===3)content=`<form id="orderForm"><div class="summary"><div class="summary-row"><span>${esc(story.title)}</span><span>${t('غلاف مقوّى','Hardcover')}</span></div><div class="summary-row"><span>${t('الكتاب والنسخة الرقمية','Book & digital copy')}</span><span>14.900 ${t('ر.ع','OMR')}</span></div><div class="summary-row"><span>${t('الشحن والضرائب','Shipping & tax')}</span><span>${t('تُحسب بعد تفعيل الخدمة','Calculated after activation')}</span></div></div><p class="notice">${t('نموذج توضيحي فقط. الدفع والطباعة والشحن غير مفعّلة، ولا تُحفظ بيانات العنوان أو تُرسل. لن يتم إنشاء طلب حقيقي.','Demo only. Payment, printing and delivery are not activated. Address details are neither stored nor sent. No real order will be placed.')}</p><div class="form-grid"><label class="field">${t('اسم المستلم','Recipient')}<input required name="recipient" autocomplete="name" maxlength="80"></label><label class="field">${t('البريد الإلكتروني','Email')}<input required type="email" name="email" autocomplete="email"></label><label class="field">${t('الدولة','Country')}<select name="country"><option>${t('الإمارات العربية المتحدة','United Arab Emirates')}</option><option>${t('المملكة العربية السعودية','Saudi Arabia')}</option><option>${t('الكويت','Kuwait')}</option><option>${t('قطر','Qatar')}</option><option>${t('البحرين','Bahrain')}</option><option>${t('عُمان','Oman')}</option></select></label><label class="field">${t('المدينة','City')}<input required name="city" autocomplete="address-level2" maxlength="80"></label><label class="field full">${t('العنوان التفصيلي','Street address')}<input required name="address" autocomplete="street-address" maxlength="200"></label></div><div class="form-actions"><button type="button" class="button outline" id="back">${t('رجوع','Back')}</button><button class="button" type="submit">${t('مراجعة الطلب التجريبي','Review demo order')}</button></div></form>`;
 $('#studioContent').innerHTML=progress+content;bindStudio();
}
function bindStudio(){
 if($('#back'))$('#back').onclick=()=>{commitPage();step--;renderStudio()};
 if($('#heroForm')){
 $('#heroForm').onsubmit=e=>{e.preventDefault();const f=new FormData(e.target);const name=f.get('name').trim();if(!name){toast(t('يرجى كتابة اسم الطفل','Please enter a child’s name'));return}Object.assign(draft,{name,age:f.get('age'),storyLanguage:f.get('storyLanguage'),dedication:f.get('dedication').trim(),consent:true});step=1;renderStudio()};
 $('#photo').onchange=e=>{const file=e.target.files[0];if(!file)return;if(!['image/jpeg','image/png','image/webp'].includes(file.type)||file.size>5*1024*1024){toast(t('اختر صورة JPG أو PNG أو WebP بحجم أقل من ٥ ميجابايت','Choose a JPG, PNG or WebP under 5 MB'));e.target.value='';return}const reader=new FileReader();reader.onload=()=>{const img=new Image();img.onload=()=>{draft.photo=reader.result;$('#photoPreview').src=reader.result};img.onerror=()=>toast(t('تعذّر قراءة الصورة','Could not read image'));img.src=reader.result};reader.readAsDataURL(file)};
 }
 document.querySelectorAll('[data-select-world]').forEach(b=>b.onclick=()=>{draft.world=b.dataset.selectWorld;draft.plan=$('#plan').value;renderStudio()});
 if($('#makeStory'))$('#makeStory').onclick=()=>{draft.plan=$('#plan').value;story=makeSample();page=0;step=2;renderStudio()};
 if($('#pageText'))$('#pageText').oninput=commitPage;
 if($('#nextPage'))$('#nextPage').onclick=()=>{commitPage();page=(page+1)%story.pages.length;renderStudio()};
 if($('#prevPage'))$('#prevPage').onclick=()=>{commitPage();page=(page+story.pages.length-1)%story.pages.length;renderStudio()};
 if($('#saveStory'))$('#saveStory').onclick=saveStory;
 if($('#downloadStory'))$('#downloadStory').onclick=downloadStory;
 if($('#filmPreview'))$('#filmPreview').onclick=()=>{commitPage();showFilm(story)};
 if($('#orderBook'))$('#orderBook').onclick=()=>{commitPage();step=3;renderStudio()};
 if($('#orderForm'))$('#orderForm').onsubmit=e=>{e.preventDefault();const f=new FormData(e.target);const recipient=esc(f.get('recipient')),city=esc(f.get('city'));$('#viewerTitle').textContent=t('مراجعة تجريبية — لم يُرسل طلب','Demo review — no order submitted');$('#viewerContent').innerHTML=`<div class="summary"><h3>${esc(story.title)}</h3><p>${recipient} · ${city}</p><p>${esc(f.get('address'))} · ${esc(f.get('country'))}</p><strong>14.900 ${t('ر.ع + الشحن والضرائب بعد التفعيل','OMR + shipping & tax after activation')}</strong></div><p class="notice">${t('لم يتم تحصيل أي مبلغ. لاستقبال طلبات فعلية، يجب ربط بوابة الدفع ومزوّد الطباعة والشحن.','No payment collected. Live ordering requires a payment gateway and print and shipping providers.')}</p>`;$('#viewer').showModal()};
}
function makeSample(){const n=draft.name,a=draft.storyLanguage==='ar',w=draft.world;const items={forest:a?['غابة تتلألأ أوراقها','ثعلب صغير','شجرة الأمنيات','بذرة ذهبية']:['a forest of shimmering leaves','a little fox','the wishing tree','a golden seed'],space:a?['كوكب بين النجوم','روبوت صغير','نجمة ضائعة','خريطة فضائية']:['a planet among the stars','a little robot','a lost star','a space map'],ocean:a?['مملكة المرجان','سلحفاة صغيرة','لؤلؤة البحر','صدفة مضيئة']:['the coral kingdom','a little turtle','the ocean pearl','a glowing shell']}[w];const [place,friend,goal,key]=items;const pages=a?[`كان يا ما كان، طفل اسمه ${n}، يحمل في قلبه فضولًا أكبر من العالم.`,draft.dedication||`في صباح جميل، وجد ${n} رسالة صغيرة تقول: «كل مغامرة تبدأ بخطوة شجاعة».`,`أغمض ${n} عينيه، وحين فتحهما وجد نفسه في ${place}.`,`هناك، ظهر ${friend} وقال: «كنت أنتظرك! نحتاج إلى مساعدتك».`,`كانت مهمتهما البحث عن ${goal}، الذي اختفى خلف ضباب ناعم.`,`لم يعرف ${n} الطريق، لكنه قرر أن يسمع لصديقه ويتعاونا معًا.`,`وعند مفترق الطرق، وجدا ${key}. كانت تتوهج كلما فعلا شيئًا لطيفًا.`,`ساعد ${n} عصفورًا صغيرًا، فأنارت لهما العلامات الطريق.`,`تعب الصديقان قليلًا. قال ${n}: «لا بأس أن نستريح ثم نحاول من جديد».`,`وأخيرًا، وصلا إلى ${goal}. لم يحتجا قوة خارقة، بل قلبًا طيبًا وفكرة ذكية.`,`ضحك ${friend} وقال: «البطل الحقيقي يساعد الآخرين، حتى حين يشعر بالخوف».`,`عاد ${n} إلى بيته، وفي قلبه سر جميل: الشجاعة والصداقة تجعل كل يوم حكاية جديدة.`]:[`Once upon a time, a child named ${n} held a world of curiosity in their heart.`,draft.dedication||`One bright morning, ${n} found a note: “Every adventure starts with one brave step.”`,`${n} closed their eyes and opened them in ${place}.`,`There, ${friend} appeared. “I’ve been waiting for you! We need your help.”`,`Together, they set out to find ${goal}, hidden behind a gentle mist.`,`${n} did not know the way, so they listened to their friend and made a plan together.`,`At a crossroads, they discovered ${key}. It glowed whenever someone did something kind.`,`${n} helped a tiny bird, and bright little signs appeared along the path.`,`The friends grew tired. “We can rest, then try again,” said ${n}.`,`At last they found ${goal}. It took a kind heart and a clever idea, rather than super strength.`,`“A real hero helps others, even when they feel afraid,” said ${friend} with a smile.`,`${n} came home with a beautiful secret: courage and friendship can turn every day into a story.`];return{id:crypto.randomUUID(),name:n,world:w,language:draft.storyLanguage,title:a?`${n} و${titleFor(w,'ar')}`:`${n} & ${titleFor(w,'en')}`,pages,createdAt:new Date().toISOString(),sample:true}}
function commitPage(){if($('#pageText')&&story)story.pages[page]=$('#pageText').value}
function getLibrary(){try{const data=JSON.parse(localStorage.getItem('hikaya-stories')||'[]');return Array.isArray(data)?data.filter(s=>s&&typeof s.id==='string'&&typeof s.title==='string'&&worlds.includes(s.world)&&Array.isArray(s.pages)&&s.pages.every(p=>typeof p==='string')):[]}catch{return[]}}
function saveStory(){commitPage();try{const list=getLibrary().filter(s=>s.id!==story.id);localStorage.setItem('hikaya-stories',JSON.stringify([story,...list].slice(0,30)));toast(t('حُفظت القصة في مكتبتك على هذا الجهاز','Saved to your library on this device'))}catch{toast(t('تعذّر الحفظ. يمكنك تنزيل القصة بدلًا من ذلك.','Storage unavailable. You can download the story instead.'))}}
function download(blob,name){const url=URL.createObjectURL(blob);const a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),10000)}
function downloadStory(){commitPage();const a=story.language==='ar';const html=`<!doctype html><html lang="${a?'ar':'en'}" dir="${a?'rtl':'ltr'}"><meta charset="utf-8"><title>${esc(story.title)}</title><style>body{font:20px/2.1 system-ui;color:#164b42;max-width:700px;margin:50px auto;padding:25px;background:#faf9f5}h1{font-size:38px}section{padding:35px 0;border-bottom:1px solid #ddd;break-inside:avoid}small{font-size:13px;color:#777}@media print{section{break-after:page}button{display:none}}</style><h1>${esc(story.title)}</h1><small>${a?'حكاية · نص قصة تجريبي قابل للطباعة. لحفظ PDF استخدم طباعة المتصفح.':'Hikaya · Printable sample story text. Use your browser’s print menu to save as PDF.'}</small>${story.pages.map((p,i)=>`<section><small>${i+1} / ${story.pages.length}</small><p>${esc(p)}</p></section>`).join('')}</html>`;download(new Blob([html],{type:'text/html;charset=utf-8'}),'hikaya-story.html');toast(t('تم تنزيل نص القصة. افتح الملف واطبعه لحفظ PDF.','Story text downloaded. Open and print the file to save a PDF.'))}
$('#library').onclick=showLibrary;
function showLibrary(){const list=getLibrary();$('#viewerTitle').textContent=t('مكتبتي','My library');$('#viewerContent').innerHTML=list.length?`<p class="notice">${t('تُحفظ القصص في هذا المتصفح فقط، دون صورة الطفل. نزّل نسخة للاحتفاظ بها.','Stories are saved only in this browser, without the child’s photo. Download a copy to keep it.')}</p>`+list.map(s=>`<div class="library-item"><div><h3>${esc(s.title)}</h3><small>${new Date(s.createdAt).toLocaleDateString(lang==='ar'?'ar-AE':'en-GB')}</small></div><div><button class="button outline" data-open="${esc(s.id)}">${t('فتح','Open')}</button> <button class="button outline" data-delete="${esc(s.id)}">${t('حذف','Delete')}</button></div></div>`).join(''):`<div class="empty">✧<h3>${t('حكايتك الأولى تنتظرك','Your first story is waiting')}</h3><p>${t('احفظ قصة من الاستوديو لتجدها هنا.','Save a story from the studio to find it here.')}</p><button class="button" id="emptyCreate">${t('اصنع حكاية','Create a story')}</button></div>`;if(!$('#viewer').open)$('#viewer').showModal();document.querySelectorAll('[data-open]').forEach(b=>b.onclick=()=>{story=list.find(s=>s.id===b.dataset.open);draft={world:story.world,name:story.name,gender:story.gender,storyLanguage:story.language,plan:'digital',age:'6',photo:'',dedication:'',consent:true};page=0;step=2;$('#viewer').close();$('#studio').showModal();renderStudio()});document.querySelectorAll('[data-delete]').forEach(b=>b.onclick=()=>{try{localStorage.setItem('hikaya-stories',JSON.stringify(list.filter(s=>s.id!==b.dataset.delete)));showLibrary()}catch{toast(t('تعذّر الحذف','Could not delete story'))}});if($('#emptyCreate'))$('#emptyCreate').onclick=()=>{$('#viewer').close();start()}}
function showFilm(s){$('#viewerTitle').textContent=t('معاينة بصرية للحكاية','Story motion preview');$('#viewerContent').innerHTML=`<figure class="film" style="margin:0"><img src="assets/hero-family.png" alt="${t('رسم توضيحي نموذجي','Sample illustration')}"><figcaption>${esc(s.title)}</figcaption></figure><p class="notice">${t('هذه حركة معاينة لرسم نموذجي وليست فيديو مولّدًا بالذكاء الاصطناعي. تصدير الفيديو المتاح أدناه يحفظ معاينة صامتة بصيغة WebM.','This is an animated sample illustration, not an AI-generated video. The export below saves a silent WebM preview.')}</p><div class="film-controls"><button class="button outline" id="narrate">${t('▶ قراءة النص','▶ Read story')}</button><button class="button" id="exportVideo">${t('تنزيل المعاينة WebM','Download preview WebM')}</button></div>`;$('#viewer').showModal();$('#narrate').onclick=()=>{if(speechSynthesis.speaking){speechSynthesis.cancel();$('#narrate').textContent=t('▶ قراءة النص','▶ Read story');return}const utterance=new SpeechSynthesisUtterance(s.pages.join(' '));utterance.lang=s.language==='ar'?'ar-SA':'en-US';utterance.onend=()=>{if($('#narrate'))$('#narrate').textContent=t('▶ قراءة النص','▶ Read story')};speechSynthesis.speak(utterance);$('#narrate').textContent=t('■ إيقاف القراءة','■ Stop reading')};$('#exportVideo').onclick=()=>exportVideo(s)}
async function exportVideo(s){const button=$('#exportVideo');if(!window.MediaRecorder||!HTMLCanvasElement.prototype.captureStream){toast(t('تصدير الفيديو غير مدعوم في هذا المتصفح','Video export is not supported in this browser'));return}button.disabled=true;button.textContent=t('جارٍ إعداد المعاينة…','Preparing preview…');let stream;try{const img=new Image();img.src='assets/hero-family.png';await img.decode();const canvas=document.createElement('canvas');canvas.width=1280;canvas.height=720;const ctx=canvas.getContext('2d');stream=canvas.captureStream(24);const type=['video/webm;codecs=vp9','video/webm;codecs=vp8','video/webm'].find(m=>MediaRecorder.isTypeSupported(m));if(!type)throw Error('unsupported');const rec=new MediaRecorder(stream,{mimeType:type});const chunks=[];const done=new Promise(resolve=>{rec.ondataavailable=e=>{if(e.data.size)chunks.push(e.data)};rec.onstop=resolve});rec.start();const start=performance.now();await new Promise(resolve=>{function frame(now){const p=Math.min((now-start)/6000,1),scale=1+p*.08;const w=1280*scale,h=w*img.height/img.width;ctx.drawImage(img,(1280-w)/2,(720-h)/2,w,h);ctx.fillStyle='rgba(12,40,32,.65)';ctx.fillRect(0,550,1280,170);ctx.fillStyle='white';ctx.textAlign='center';ctx.direction=s.language==='ar'?'rtl':'ltr';ctx.font='bold 30px sans-serif';ctx.fillText(s.title,640,615,1180);ctx.font='18px sans-serif';ctx.fillText(s.language==='ar'?'حكاية · معاينة متحركة تجريبية':'Hikaya · Animated sample preview',640,665);if(p<1)requestAnimationFrame(frame);else resolve()}requestAnimationFrame(frame)});rec.stop();await done;download(new Blob(chunks,{type:'video/webm'}),'hikaya-preview.webm');toast(t('تم تنزيل المعاينة المتحركة','Animated preview downloaded'))}catch{toast(t('تعذّر تصدير الفيديو في هذا المتصفح','Could not export video in this browser'))}finally{stream?.getTracks().forEach(track=>track.stop());button.disabled=false;button.textContent=t('تنزيل المعاينة WebM','Download preview WebM')}}
function example(){const prev=draft;draft={name:lang==='ar'?'عيسى':'Isa',world:'forest',storyLanguage:lang,dedication:''};const s=makeSample();draft=prev;return s}
$('#watch').onclick=()=>showFilm(example());$('#openExample').onclick=()=>{story=example();draft={name:story.name,world:story.world,storyLanguage:story.language,age:'6',plan:'digital',photo:'',consent:true,dedication:''};page=0;step=2;$('#studio').showModal();renderStudio()};
$('#privacy').onclick=()=>{$('#viewerTitle').textContent=t('خصوصية طفلك أولًا','Your child’s privacy comes first');$('#viewerContent').innerHTML=`<p class="preview-text">${t('هذه نسخة تجريبية. لا تُرسل الصورة التي تختارها أو بيانات العنوان إلى خادم، ولا تُحفظ صورة الطفل في المكتبة. تُحفظ القصص التي تختار حفظها في ذاكرة هذا المتصفح فقط ويمكن حذفها من المكتبة. تُحمّل الخطوط من Google Fonts. عند تفعيل الخدمات مستقبلًا، يلزم نشر سياسة واضحة للاحتفاظ بالصور وحذفها وموافقة ولي الأمر قبل استقبال بيانات حقيقية.','This is a demo. Selected photos and address details are not sent to a server. Child photos are not saved in the library. Stories you choose to save are stored only in this browser and can be deleted from the library. Fonts load from Google Fonts. Before live services are activated, publish a policy covering image retention, deletion, and parental consent.')}</p>`;$('#viewer').showModal()};
